import React from "react";
import RedditFeed from "./components/RedditFeed";

function App() {
  return (
    <div
      className="dashboard dark-theme"
      style={{
        padding: "1rem",
        background: "#121212",
        color: "#ccc",
        minHeight: "100vh",
        fontFamily: "Arial, sans-serif",
      }}
    >
      <h1 style={{ color: "#4da6ff", marginBottom: "1rem" }}>🔶 ReleaseTrain Reddit Feed</h1>
      <div style={{ display: "flex", gap: "1rem" }}>
        <div style={{ flex: 1 }}>
          <RedditFeed />
        </div>
      </div>
    </div>
  );
}

export default App;
